drop policy if exists enterprise_partner_network_metrics_admin_read on public.enterprise_partner_network_metrics;
create policy enterprise_partner_network_metrics_scoped_read on public.enterprise_partner_network_metrics for select to authenticated using (is_platform_owner(auth.uid()) or exists (select 1 from public.enterprise_partner_networks n where n.id=enterprise_partner_network_metrics.network_id and (exists (select 1 from public.business_members bm where bm.business_id=n.owner_business_id and bm.user_id=auth.uid()) or exists (select 1 from public.enterprise_partner_network_members nm join public.business_members bm on bm.business_id=nm.partner_business_id where nm.network_id=n.id and nm.status='active' and bm.user_id=auth.uid()))));

drop policy if exists reporting_runs_owner_select on public.reporting_runs;
create policy reporting_runs_scoped_select on public.reporting_runs for select to authenticated using (exists (select 1 from public.reporting_schedules s where s.id=reporting_runs.schedule_id and (s.owner_id=auth.uid() or is_platform_owner(auth.uid()) or exists (select 1 from public.business_members bm where bm.business_id=s.scope_id and bm.user_id=auth.uid()))));

drop policy if exists reporting_schedules_owner_select on public.reporting_schedules;
create policy reporting_schedules_scoped_select on public.reporting_schedules for select to authenticated using (owner_id=auth.uid() or is_platform_owner(auth.uid()) or (scope_type='business' and exists (select 1 from public.business_members bm where bm.business_id=reporting_schedules.scope_id and bm.user_id=auth.uid())));

drop policy if exists reporting_schedules_owner_update on public.reporting_schedules;
create policy reporting_schedules_scoped_update on public.reporting_schedules for update to authenticated using (owner_id=auth.uid() or is_platform_owner(auth.uid()) or (scope_type='business' and exists (select 1 from public.business_members bm where bm.business_id=reporting_schedules.scope_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','manager','fleet_owner','fleet_manager','enterprise_owner','enterprise_admin','enterprise_manager')))) with check (owner_id=auth.uid() or is_platform_owner(auth.uid()) or (scope_type='business' and exists (select 1 from public.business_members bm where bm.business_id=reporting_schedules.scope_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','manager','fleet_owner','fleet_manager','enterprise_owner','enterprise_admin','enterprise_manager'))));
